#!/usr/bin/env python3
"""Alfred Script Filter: list local TLDR pages and launch a weekly refresh."""

import json
import os
import subprocess
import sys
import time
from pathlib import Path

# Keep this aligned with the original workflow, which uses ./pages.
workflow_dir = Path.cwd().resolve()
pages_dir = workflow_dir / "pages"
updater = workflow_dir / "update_pages.py"
success_marker = workflow_dir / ".tldr-pages-last-success"
attempt_marker = workflow_dir / ".tldr-pages-last-attempt"
lock_path = workflow_dir / ".tldr-pages-update.lock"

WEEK_SECONDS = 7 * 24 * 60 * 60
RETRY_SECONDS = 24 * 60 * 60
STALE_LOCK_SECONDS = 60 * 60


def read_timestamp(path: Path) -> float:
    try:
        return float(path.read_text(encoding="utf-8").strip())
    except (OSError, ValueError):
        return 0.0


def maybe_start_update() -> None:
    now = time.time()
    if not updater.is_file():
        return
    if now - read_timestamp(success_marker) < WEEK_SECONDS:
        return
    if now - read_timestamp(attempt_marker) < RETRY_SECONDS:
        return

    # Clear a stale lock left behind by an interrupted updater.
    try:
        if lock_path.exists() and now - lock_path.stat().st_mtime > STALE_LOCK_SECONDS:
            lock_path.unlink()
    except OSError:
        pass

    try:
        fd = os.open(str(lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        os.close(fd)
    except FileExistsError:
        return
    except OSError:
        return

    try:
        attempt_marker.write_text(str(now), encoding="utf-8")
        subprocess.Popen(
            [
                sys.executable,
                str(updater),
                str(pages_dir),
                str(success_marker),
                str(lock_path),
            ],
            cwd=str(workflow_dir),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
    except OSError:
        lock_path.unlink(missing_ok=True)


maybe_start_update()

# Return cached results immediately; never wait for the network download.
items = []
if pages_dir.is_dir():
    for platform in sorted(pages_dir.iterdir()):
        if not platform.is_dir():
            continue
        for page_file in sorted(platform.glob("*.md")):
            items.append(
                {
                    "title": page_file.stem.replace("-", " "),
                    "subtitle": platform.name,
                    "arg": str(page_file.resolve()),
                }
            )

print(json.dumps({"items": items}, ensure_ascii=False))
